eACC,CAAA,mCAGD,cACC,CAAA,uCACA,CAAA,eACA,CAAA,yCAEA,iBACC,CAAA,+CAEA,gBACC,CAAA,sJAGD,oBAGC,CAAA,wCAIF,cACC,CAAA,mCACA,CAAA,gBACA,CADA,mBACA,CAAA,kBACA,CADA,mBACA,CAAA,qCACA,CAAA,6CAGD,kBACC,CAAA,eACA,CAAA,sBACA,CAAA,aAKH,UAIC,qBAEC,CAAA,qBACA,CAAA,QACA,CAAA,eACA,CAAA,UACA,CAAA,UACA,CAAA,WACA,CAAA,QACA,CAAA,cACA,CAAA,YACA,CAAA,SACA,CAAA,eACA,CAAA,UACA,CAAA,SACA,CAAA,kBACA,CAAA,eACA,CAAA,aACA,CAAA,KAGD,YACC,CAAA,aACA,CAAA,MAMD,uBAEC,CAAA,iBAGD,sBAIC,CAAA,iCAGD,UAEC,CAAA,qBACA,CAAA",sourcesContent:["\n$path-images: \"~@proton/styles/assets/img/illustrations/\";\n\n\n$use-vertical-align-img-iframe: false;\n\n@import '~@proton/styles/scss/config';\n@import '@proton/styles/scss/base/reset';\n@import '@proton/styles/scss/base/scrollbar';\n@import '@proton/styles/scss/base/custom-properties';\n\n/* ----------------------\n      EMAIL RESET\n------------------------ */\n\nbody {\n\t/* in case nothing is set, set a default font and size */\n\tfont-family: system-ui, sans-serif;\n\tfont-size: em($base-font-size, $root-default-font-size);\n\n\t/* this is clearly needed if we want consistency  */\n\ttext-rendering: geometricprecision;\n\t-webkit-font-smoothing: antialiased;\n\toverflow-y: hidden;\n\toverflow-x: auto;\n}\n\n/* override reset.scss */\nbody * {\n\tline-height: 1.5;\n}\n\ncode {\n\tline-height: 1;\n}\n\n/* Forbidden property on almost ALL clients IE add a space :) */\n[style*='position:absolute'],\n[style*='position: absolute'] {\n\tposition: relative !important;\n}\n\n/* Forbidden height with pourcentage on images */\nimg[height$='%'] {\n\tblock-size: unset !important;\n}\n\n// remove reset margins\nblockquote,\ndl,\nol,\np,\npre,\ntd,\nth,\nul {\n\tmargin-block: 0;\n}\n\np {\n\tmargin-block: 1em;\n}\n\ntable {\n\tmargin-block-end: 0;\n\ttable-layout: auto;\n}\n\nblockquote {\n\tpadding-block: 0;\n\tpadding-inline: rem(16) 0;\n\tmargin: 0;\n\tborder-inline-start: 4px solid #e5e5e5;\n\n\t&::after,\n\t&::before {\n\t\tcontent: none;\n\t}\n}\n\n// fix for some embedded images bugs\nimg {\n\tmax-inline-size: none;\n}\n\npre,\ncode {\n\twhite-space: pre-wrap;\n\tbackground-color: transparent;\n}\n\n/* ---------------------------------\n      CUSTOM STYLES AND HELPERS\n----------------------------------- */\na {\n\tcolor: var(--interaction-norm);\n\ttext-decoration: underline;\n\tcursor: pointer;\n}\n\na:hover,\na:focus {\n\tcolor: var(--interaction-norm-hover);\n\ttext-decoration: none;\n}\n\na:active {\n\tcolor: var(--interaction-norm-active);\n\ttext-decoration: none;\n}\n\n/**\n * Avoid overflow management on #proton-root.\n * Better to handle it in body because risk of wrong height calculation\n */\n#proton-root {\n\tbox-sizing: content-box;\n\tmax-inline-size: none;\n}\n\n.proton-dark-style {\n\tcolor: var(--text-norm);\n\tbackground-color: var(--background-norm);\n}\n\n.proton-hidden {\n\tdisplay: none;\n}\n\n.proton-sr-only {\n\tborder: 0;\n\tclip: rect(0 0 0 0);\n\tblock-size: 1px;\n\tmargin: -1px;\n\toverflow: hidden;\n\tpadding: 0;\n\tposition: absolute;\n\tinline-size: 1px;\n\tinset-block-start: 0; // needed for Safari dumb and 💩 behaviour\n}\n\n.icon-14p {\n\tinline-size: 14px;\n\tblock-size: 14px;\n}\n\n/*\n * 1. do not handle responsivess if there is a width attribute / inline width style\n * 2. do not set auto height as long as it's not need to handle our embedded images (no height attribute)\n * 3. set at least a min width or it's possible it won't be shown\n * 4. remove min-inline-size when image loaded - for tiny images\n */\n.proton-embedded:not([width], [style*='width']) {\n\tmax-inline-size: 100%;\n\tmin-inline-size: 38px;\n}\n\n.proton-embedded:not([width], [style*='width'])[src] {\n\tmin-inline-size: 0;\n}\n\nblockquote.protonmail_quote {\n\tpadding-block: 0.2em;\n\tpadding-inline: 1.2em 0;\n\tborder-color: #657ee4;\n\tborder-inline-start-width: 3px;\n\tborder-inline-start-style: solid;\n}\n\nblockquote.protonmail_quote\n\tblockquote.protonmail_quote\n\tblockquote.protonmail_quote\n\tblockquote.protonmail_quote\n\tblockquote.protonmail_quote\n\tblockquote.protonmail_quote {\n\tpadding-inline: 0;\n\tborder-inline-start-width: 0;\n}\n\n/* -----------------------\n\tPLAIN TEXT\n------------------------- */\n\n.proton-plain-text {\n\tfont-family: $font-family-monospace;\n\tbackground: var(--background-norm);\n\tcolor: var(--text-norm);\n\twhite-space: pre-wrap;\n\ttext-rendering: geometricprecision;\n\t-webkit-font-smoothing: antialiased;\n}\n\n/* ---------------------------------\n      BUTTONS\n----------------------------------- */\n\n.proton-toggle-button {\n\tdisplay: inline-block;\n\tpadding-block: rem(4);\n\tpadding-inline: rem(8);\n\tmargin: 1em;\n\tmargin-inline-start: 0;\n\tbox-shadow: inset 0 0 0 1px silver;\n\tborder: none;\n\tborder-radius: var(--border-radius-md);\n\toutline: none;\n\tbackground-color: transparent;\n\ttext-align: center;\n\ttransition: 0.15s cubic-bezier(0.22, 1, 0.36, 1), background-position 0s;\n\n\t&:hover,\n\t&:focus,\n\t&:focus-within &.is-hover &:active,\n\t&.is-active,\n\t&[aria-expanded='true']:not([aria-controls]) {\n\t\ttext-decoration: none;\n\t\tbox-shadow: inset 0 0 0 2px silver;\n\t\tbackground-color: transparent;\n\t}\n}\n\n@supports selector(:focus-visible) {\n\t.proton-toggle-button {\n\t\toutline: unset;\n\t}\n}\n\n/* ---------------------------------\n      IMAGE PLACEHOLDER\n----------------------------------- */\n\n.proton-image-placeholder {\n\t/* stylelint-disable-next-line color-hex-length */\n\tbackground-color: #00000011;\n\tbox-sizing: border-box;\n\tdisplay: inline-flex;\n\tborder: 1px solid var(--border-norm);\n\tborder-radius: var(--border-radius-md);\n\tjustify-content: center;\n\talign-items: center;\n\tcolor: black;\n\tmargin-block-end: 7px;\n\tmargin-inline-end: 7px;\n}\n\n.proton-image-placeholder--error {\n\tcolor: #d42f34;\n\tborder-color: #d42f34;\n}\n\n.proton-image-placeholder .icon-20p {\n\tinline-size: 1.25rem;\n\tblock-size: 1.25rem;\n\tdisplay: inline-block;\n\tvertical-align: middle;\n\tfill: currentcolor;\n}\n\n@keyframes anime-loader-rotation {\n\tfrom {\n\t\ttransform: rotate(0);\n\t}\n\n\tto {\n\t\ttransform: rotate(360deg);\n\t}\n}\n\n.proton-circle-loader {\n\tfont-size: 20px;\n\tdisplay: inline-block;\n\tinline-size: 1em;\n\tblock-size: 1em;\n\ttransform-origin: 50%;\n\tvertical-align: middle;\n\tanimation: anime-loader-rotation 2s linear infinite;\n}\n\n.proton-circle-loader-track {\n\tstroke: currentcolor;\n\topacity: 0.2;\n}\n\n.proton-circle-loader-track,\n.proton-circle-loader-circle {\n\tfill: none;\n\tstroke-width: 20;\n\tstroke-linecap: round;\n}\n\n@keyframes anime-loader-stroke {\n\t0% {\n\t\tstroke-dashoffset: 440;\n\t}\n\n\t50% {\n\t\tstroke-dashoffset: 0;\n\t}\n\n\t50.1% {\n\t\tstroke-dashoffset: 880;\n\t}\n}\n\n.proton-circle-loader-circle {\n\tstroke: currentcolor;\n\tstroke-dasharray: 440;\n\tstroke-dashoffset: 440;\n\tanimation: anime-loader-stroke 4s linear infinite;\n}\n\n/* ---------------------\n        PRINT\n------------------------ */\n\n.proton-print {\n\t/* stylelint-disable-next-line no-invalid-position-at-import-rule */\n\t@import '~@proton/styles/scss/helpers/flex';\n\t/* stylelint-disable-next-line no-invalid-position-at-import-rule */\n\t@import '~@proton/styles/scss/helpers/outline';\n\n\tfont-family: var(--font-family);\n\tfont-size: 14px;\n\tline-height: 1.5;\n\tcolor: var(--text-norm);\n\tbackground-color: var(--background-norm);\n\ttext-rendering: geometricprecision;\n\t-webkit-font-smoothing: antialiased;\n\tpadding-block-end: 1em;\n\toverflow: auto;\n\n\t.message-print-subject {\n\t\tfont-size: 20px;\n\t\tborder-block-end: 1px solid var(--border-norm);\n\t\tmargin-block-end: 0.5em;\n\t\tpadding-block-end: 0.5em;\n\t}\n\n\t.message-print-header {\n\t\tborder-block-end: 1px solid var(--border-weak);\n\t\tpadding-block-end: 1em;\n\t}\n\n\t.message-recipient-item-expanded {\n\t\tmargin-block-start: 0.75em;\n\t}\n\n\t.container-to {\n\t\tmin-inline-size: 3em;\n\t}\n\n\t.item-icon,\n\t.container-to.container-to--item {\n\t\tdisplay: none;\n\t}\n\n\t.item-date {\n\t\tfont-size: 1em;\n\t}\n\n\t.color-weak {\n\t\tcolor: var(--text-norm);\n\t}\n\n\t.maxw-100 {\n\t\tmax-inline-size: 100%;\n\t}\n\n\t.text-ellipsis {\n\t\toverflow: hidden;\n\t\ttext-overflow: ellipsis;\n\t\twhite-space: nowrap;\n\t}\n\n\t.inline-block {\n\t\tdisplay: inline-block;\n\t}\n\n\t.text-pre {\n\t\twhite-space: pre;\n\t}\n\n\t.proton-print-footer {\n\t\tmargin-block-start: 1em;\n\t\tborder-block-start: 1px solid var(--border-weak);\n\t\tpadding-block-start: 1em;\n\n\t\t&-sizes {\n\t\t\tmargin-block-end: 1em;\n\n\t\t\t&-label {\n\t\t\t\tmargin-inline-end: 1em;\n\t\t\t}\n\n\t\t\t&-label,\n\t\t\t&-count,\n\t\t\t&-embedded-count {\n\t\t\t\talign-items: baseline;\n\t\t\t}\n\t\t}\n\n\t\t&-item {\n\t\t\tmax-inline-size: 100%;\n\t\t\tborder: 1px solid var(--border-weak);\n\t\t\tpadding-block: 0.5em;\n\t\t\tpadding-inline: 0.25em;\n\t\t\tborder-radius: var(--border-radius-md);\n\t\t}\n\n\t\t&-item-size {\n\t\t\tmargin-inline-start: 0.25rem;\n\t\t\tfont-size: 0.75em;\n\t\t\tcolor: var(--text-weak);\n\t\t}\n\t}\n}\n\n@media print {\n\t/**\n    * add in this all elements which need to be hardly reseted for print\n    */\n\tbody,\n\thtml {\n\t\tbackground-color: white;\n\t\tbackground-image: none;\n\t\tborder: 0;\n\t\tbox-shadow: none;\n\t\tcolor: black;\n\t\tfloat: none;\n\t\tblock-size: auto;\n\t\tmargin: 0;\n\t\tmax-inline-size: 100%;\n\t\tmin-block-size: 0;\n\t\tpadding: 0;\n\t\tposition: static;\n\t\tinline-size: auto;\n\t\topacity: 1;\n\t\tvisibility: visible;\n\t\tmax-block-size: none;\n\t\tdisplay: block;\n\t}\n\n\tbody {\n\t\tpadding: 0.5em;\n\t\toverflow: auto;\n\t}\n\n\t/**\n    * avoid problematic page break\n    */\n\tul,\n\tol {\n\t\tpage-break-inside: avoid;\n\t}\n\n\th1,\n\th2,\n\th3,\n\tcaption {\n\t\tpage-break-after: avoid;\n\t}\n\n\t.proton-print,\n\t.proton-plain-text {\n\t\tcolor: black;\n\t\tbackground-color: white;\n\t}\n}\n","article,\naside,\ndatalist,\ndetails,\ndialog,\nfigure,\nfooter,\nheader,\